"""Generate manuscript-ready eICU external-validation text and audit mapping."""
from __future__ import annotations
import argparse,json,sys
from pathlib import Path
import pandas as pd
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
from src.paths import RESULTS_DIR  # noqa:E402

def ci(row,metric):return f"{row[metric]:.3f} (95% CI {row[metric+'_ci_lower']:.3f}-{row[metric+'_ci_upper']:.3f})"
def main():
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('--output',default=RESULTS_DIR/'eicu_external_validation/manuscript_text');a=p.parse_args();out=Path(a.output);out.mkdir(parents=True,exist_ok=True)
 flow=json.loads((RESULTS_DIR/'eicu_external_validation/sepsis3_mof_cohort/cohort_flow_counts.json').read_text());perf=pd.read_csv(RESULTS_DIR/'eicu_external_validation/locked_model_performance/table_external_validation_performance.csv');raw=perf.query("model=='Raw locked model'").iloc[0];cal=perf.query("model=='Development-calibrated locked model'").iloc[0];hosp=pd.read_csv(RESULTS_DIR/'eicu_external_validation/hospital_robustness/table_hospital_bootstrap_performance.csv').set_index('metric');sub=pd.read_csv(RESULTS_DIR/'eicu_external_validation/locked_model_performance/table_external_validation_subgroups.csv');explicit=sub.query("subgroup=='Explicit sepsis-text subgroup' and model=='Raw'").iloc[0];complete=sub.query("subgroup=='At least 4 observed SOFA components' and model=='Raw'").iloc[0]
 methods=f'''## External validation cohort and outcome

We performed multicentre external validation using the eICU Collaborative Research Database version 2.0. Adult ICU stays were screened using a pragmatic, time-resolved adaptation of the Sepsis-3 framework necessitated by incomplete capture of negative culture orders in eICU. Suspected infection required a documented infection-related diagnosis accompanied by a systemic antibiotic administered from 24 hours before through 72 hours after the diagnosis. Six organ-specific Sequential Organ Failure Assessment (SOFA) components were calculated hourly using the worst values in the preceding 24 hours. Sepsis-3 eligibility required a total SOFA score of at least 2 from 48 hours before through 24 hours after suspected infection, with the qualifying SOFA assessment occurring no later than ICU hour 24.

The prediction index was ICU hour 24. As in the MIMIC-IV derivation analysis, multiple organ failure (MOF) was defined as two or more simultaneous organ-specific SOFA components with scores of at least 2 during ICU hours 24-72. Stays with two or more failing organ systems during the first 24 hours were excluded, thereby restricting the outcome to incident MOF. The same 0-24-hour predictor definitions and units used in MIMIC-IV were reproduced in eICU where semantically compatible. The eICU admission-type field had no direct equivalent to the MIMIC-IV admission categories and was therefore treated as unavailable rather than assigned through an arbitrary crosswalk.

The final CatBoost pipeline, including all preprocessing and imputation parameters estimated in MIMIC-IV, was locked before external evaluation. No model coefficients, hyperparameters, decision thresholds, or imputation values were estimated using eICU outcomes. Discrimination was assessed with the area under the receiver operating characteristic curve (AUROC) and area under the precision-recall curve (AUPRC), overall accuracy of predicted probabilities with the Brier score, and calibration using calibration intercept and slope. Confidence intervals were obtained from 5,000 patient-level bootstrap resamples. Multicentre robustness was examined separately using 5,000 bootstrap resamples with hospital as the sampling unit. A Platt transformation learned exclusively from out-of-fold MIMIC-IV development predictions was evaluated as a prespecified secondary analysis; no recalibration was fitted to eICU.
'''
 results=f'''## External validation results

Of {flow['all_eicu_stays']:,} eICU ICU stays, {flow['adult_timed_infection_candidates']:,} met the adult time-linked infection and antibiotic criteria, and {flow['infection_candidates_with_sofa_ge_2_in_sepsis3_window']:,} had a rolling SOFA score of at least 2 within the prespecified Sepsis-3 window. After requiring qualification by ICU hour 24, excluding prevalent MOF during the first 24 hours, and requiring follow-up during hours 24-72, the external validation cohort included {flow['final_eligible_stays']:,} ICU stays from {flow['unique_patients']:,} patients. Incident MOF occurred in {flow['mof_events_24_to_72h']:,} stays ({flow['mof_prevalence']*100:.1f}%).

The locked CatBoost model achieved an AUROC of {ci(raw,'AUROC')} and an AUPRC of {ci(raw,'AUPRC')} in eICU. The Brier score was {ci(raw,'Brier score')}. The calibration intercept was {raw.calibration_intercept:.3f}, and the calibration slope was {raw.calibration_slope:.3f}. The model retained discrimination in the explicit sepsis-text subgroup (n={int(explicit['n']):,}; AUROC={explicit.AUROC:.3f}; AUPRC={explicit.AUPRC:.3f}) and among stays with at least four observed SOFA components at qualification (n={int(complete['n']):,}; AUROC={complete.AUROC:.3f}; AUPRC={complete.AUPRC:.3f}).

Hospital-level resampling produced an AUROC of {hosp.loc['AUROC','estimate']:.3f} (95% CI {hosp.loc['AUROC','hospital_bootstrap_ci_lower']:.3f}-{hosp.loc['AUROC','hospital_bootstrap_ci_upper']:.3f}) and an AUPRC of {hosp.loc['AUPRC','estimate']:.3f} (95% CI {hosp.loc['AUPRC','hospital_bootstrap_ci_lower']:.3f}-{hosp.loc['AUPRC','hospital_bootstrap_ci_upper']:.3f}), supporting that aggregate performance was not driven solely by a small number of centres. The MIMIC-IV-derived Platt transformation did not improve transportability: its external Brier score was {cal['Brier score']:.4f}, calibration intercept was {cal.calibration_intercept:.3f}, and calibration slope was {cal.calibration_slope:.3f}, compared with {raw['Brier score']:.4f}, {raw.calibration_intercept:.3f}, and {raw.calibration_slope:.3f}, respectively, for the raw locked model. The raw locked model was therefore retained as the primary external-validation result.

## External validation limitation for Discussion

The eICU microbiology table predominantly contains organism and susceptibility results and does not enumerate all negative culture orders. Consequently, a culture-antibiotic definition would have produced a small and selected cohort. We therefore used a transparent diagnosis-antibiotic timing adaptation for the primary eICU analysis and retained the available culture-antibiotic cohort only as a high-specificity sensitivity definition. This difference from the official MIMIC-IV suspected-infection implementation, together with cross-database variation in measurement completeness and ICU case mix, should be considered when interpreting the reduction in external discrimination.
'''
 (out/'external_validation_methods_and_results.md').write_text(methods+'\n'+results,encoding='utf-8')
 legends='''## Figure legends

**Figure X. Discrimination of the locked CatBoost model in the eICU external-validation cohort.** Receiver operating characteristic and precision-recall curves were calculated in 7,514 eligible ICU stays. The model and preprocessing pipeline were fitted exclusively in MIMIC-IV and were applied to eICU without refitting.

**Figure Y. Calibration of the locked CatBoost model in the eICU external-validation cohort.** Observed MOF proportions are plotted against mean predicted probabilities across ten quantile groups. The diagonal line denotes perfect calibration. The development-calibrated curve uses a Platt transformation estimated only from out-of-fold MIMIC-IV development predictions.

**Figure Z. Hospital-level transportability of the locked CatBoost model in eICU.** Hospital-specific AUROC estimates are displayed for hospitals with at least 100 eligible stays and at least 10 MOF events. The dashed line denotes the overall external-validation AUROC. Marker size reflects hospital sample size.
''';(out/'external_validation_figure_legends.md').write_text(legends,encoding='utf-8')
 table=perf.rename(columns={'n':'N','events':'MOF events','prevalence':'MOF prevalence','calibration_intercept':'Calibration intercept','calibration_slope':'Calibration slope'});table.to_csv(out/'table_external_validation_for_manuscript.csv',index=False)
 mapping=pd.DataFrame([
  ['External cohort identification','scripts/34_build_eicu_suspected_infection.py; scripts/35_build_eicu_timed_infection_candidates.py','suspected_infection_summary.json; candidate_cohort_flow.json'],['Hourly SOFA calculation','scripts/36_audit_eicu_sofa_sources.py; scripts/37_build_eicu_hourly_sofa.py','hourly_sofa_metadata.json; hourly_component_coverage.csv'],['Sepsis-3 and incident MOF cohort','scripts/38_build_eicu_sepsis3_mof_cohort.py','cohort_flow_counts.json; sensitivity_cohort_sizes.csv'],['Predictor harmonisation','scripts/39_build_eicu_model_features.py','feature_extraction_summary.json; eicu_feature_coverage_and_shift.csv'],['Locked-model evaluation','scripts/40_external_validate_eicu.py','table_external_validation_performance.csv; eicu_predictions.csv'],['Hospital-level robustness','scripts/41_eicu_hospital_robustness.py','table_hospital_bootstrap_performance.csv; table_hospital_specific_performance.csv'],['Cross-database comparison','scripts/42_compile_cross_database_workbook.py','mimic_eicu_cross_database_comparison.xlsx']
 ],columns=['Manuscript element','Code','Primary evidence']);mapping.to_csv(out/'external_validation_methods_code_mapping.csv',index=False)
 metadata={'language':'English','numbers_inserted_from_recorded_results':True,'external_model_refitted':False,'external_recalibration_fitted':False,'generated_files':4};(out/'manuscript_text_metadata.json').write_text(json.dumps(metadata,indent=2),encoding='utf-8');print('eICU manuscript text generated:',out)
if __name__=='__main__':main()
